import { bindings, defineConfig, exports, triggers } from "cf/config";

/**
 * DakFlare — canonical configuration for the Cloudflare CLI (`cf`).
 *
 * Generated by `cf migrate` from wrangler.toml, then completed by hand for the two
 * follow-ups it could not do:
 *
 *   1. Durable Object lifecycle. Wrangler's ordered `[[migrations]]` history is replaced by
 *      `exports`. Every class whose namespace is live must be declared here — DakFlare has
 *      exactly one, `DeviceGateway`, on the SQLite storage backend. The migration history
 *      is deliberately NOT copied: replaying applied steps would leave stale tombstones.
 *   2. Durable Object binding review. `bindings.durableObject()` needs an explicit
 *      `exportName`; it is `DeviceGateway`, the class this Worker exports.
 *
 * ## Two configs on purpose
 *
 *   cloudflare.config.ts  ← `cf` (deploy, resources, `cf d1 migrations apply`)
 *   wrangler.toml         ← `wrangler dev`, `wrangler secret put`, `wrangler tail`
 *
 * `cf` cannot set a single secret yet and cannot stream logs; Cloudflare's own migration
 * guide says to run those with `npx wrangler`. Keeping wrangler.toml also preserves the
 * local-first conformance lane, which depends on `wrangler dev --local` with Durable Object
 * SQLite, hibernating sockets and alarms.
 *
 * Do not let the two drift: whatever changes here must change there too.
 *
 * ## Durable Object lifecycle is a one-way door
 *
 * Switching from `migrations` to `exports` cannot be rolled back to a version created
 * before the switch. Land it with `cf deploy` (not a version upload), and only after the
 * export list below matches every live class.
 */

export default defineConfig({
	worker: {
		name: "dakflare-worker",
		compatibilityDate: "2026-04-07",
		// better-auth imports node:crypto in its password utilities.
		compatibilityFlags: ["nodejs_compat"],
		entrypoint: "src/index.ts",
		previewUrls: false,

		observability: {
			enabled: true,
			headSamplingRate: 1,
		},

		/**
		 * Replaces wrangler.toml's `[[migrations]] new_sqlite_classes = ["DeviceGateway"]`.
		 * `storage: "sqlite"` matches the deployed backend exactly.
		 */
		exports: {
			DeviceGateway: exports.durableObject({ storage: "sqlite" }),
			// The single globally named failed-auth counter (lib/auth-limits.ts).
			AuthGuard: exports.durableObject({ storage: "sqlite" }),
		},

		triggers: [
			triggers.scheduled({
				schedule: "17 3 * * *",
			}),
		],

		env: {
			// ── inline configuration ────────────────────────────────────────────
			// Admin auth gate: `legacy` keeps ADMIN_TOKEN; `new` uses Better Auth
			// sessions via requireRole() (see worker/src/lib/config.ts authMode).
			AUTH_LOCKOUT_WINDOW_SECONDS: bindings.text("900"),
			// The free-tier password factor: the browser runs PBKDF2, the Worker
			// only peppers and compares. Without this var the factor is `off`, so
			// a cf deploy silently disabled password sign-in that wrangler.toml
			// had been enabling.
			AUTH_PASSWORD_MODE: bindings.text("client-derived"),
			// Magic link is advertised but sends nothing until RESEND_API_KEY is
			// a Worker secret; the sandbox sender is fine until a domain exists.
			MAGIC_LINK_FROM: bindings.text("DakFlare <onboarding@resend.dev>"),
			MAGIC_LINK_TTL_SECONDS: bindings.text("900"),
			FCM_BASE_URL: bindings.text("https://fcm.googleapis.com"),
			GOOGLE_TOKEN_URL: bindings.text("https://oauth2.googleapis.com/token"),
			MESSAGE_RETENTION_DAYS: bindings.text("90"),
			INCOMING_ROWS_PER_DAY: bindings.text("10000"),
			// AGPL-3.0 §13: `/source` redirects here.
			SOURCE_URL: bindings.text("https://github.com/JonyBepary/dakflare"),

			// ── storage ─────────────────────────────────────────────────────────
			DB: bindings.d1({
				name: "sms_gateway",
				id: "8d88069e-71cf-49a2-ba33-c150b02246b7",
			}),
			KV: bindings.kv({
				id: "cabb16caf192453fa17b54b6e0f9d85f",
			}),

			// ── Durable Object ──────────────────────────────────────────────────
			DEVICE: bindings.durableObject({
				worker: "dakflare-worker",
				exportName: "DeviceGateway",
			}),
			AUTH_GUARD: bindings.durableObject({
				worker: "dakflare-worker",
				exportName: "AuthGuard",
			}),

			// ── rate limiting (hardening S3) ────────────────────────────────────
			PAIR_LIMITER: bindings.rateLimit({
				namespace: "1001",
				simple: { limit: 30, period: 60 },
			}),
			ADMIN_LIMITER: bindings.rateLimit({
				namespace: "1002",
				simple: { limit: 600, period: 60 },
			}),
			DEVICE_LIMITER: bindings.rateLimit({
				namespace: "1003",
				simple: { limit: 600, period: 60 },
			}),
			AUTH_FAIL_LIMITER: bindings.rateLimit({
				namespace: "1004",
				simple: { limit: 120, period: 60 },
			}),
			PAIR_GLOBAL_LIMITER: bindings.rateLimit({
				namespace: "1005",
				simple: { limit: 300, period: 60 },
			}),
			// Failed-auth lockout backstop (see lib/auth-limits.ts).
			AUTH_ACCOUNT_LIMITER: bindings.rateLimit({
				namespace: "1006",
				simple: { limit: 5, period: 60 },
			}),
			AUTH_IP_LIMITER: bindings.rateLimit({
				namespace: "1007",
				simple: { limit: 20, period: 60 },
			}),
		},
	},
});
